STORY_DARK_FOREST_91_100 = (
    V2StoryQuestContentRecord('dark_forest_091_unread_lines', 91, 'Непрочитані рядки', 'TALK', 'dark_forest', 10, 'dark_forest_090_corrupted_lands', 'rune_master', 'rune_master', 1, 'Рунний Майстер завершив додаткове вивчення документа, знайденого серед чорного коріння.', 'Отримати від Рунного Майстра результати подальшого вивчення документа.', 'Після першого огляду я залишив документ у захисному футлярі. Частина символів була прихована під шаром рунічного пилу, тому прочитати їх одразу не вдалося.\n\nТепер вдалося відновити кілька рядків. У них згадується місце збору біля старих кам’яних руїн. Туди мали доставляти припаси, амулети та відомості від гоблінських дозорів.\n\nІм’я одержувача не вказано. Замість нього використано символ корони над трьома зубцями. Такий знак раніше не траплявся серед наших знахідок.', 'Рунний Майстер показує відновлений фрагмент документа із символом корони над трьома зубцями.', 114, 5.29, {'reward_formula': None, 'next_route': {'npc_id': 'mercenary_head', 'route_text': '🏙️ Місто → 📜 Гільдія Найманців → ⚔️ Голова Найманців'}}),
    V2StoryQuestContentRecord('dark_forest_092_road_to_the_ruins', 92, 'Дорога до руїн', 'KILL_REGION', 'dark_forest', 10, 'dark_forest_091_unread_lines', 'mercenary_head', 'mercenary_head', 8, 'Шлях у напрямку старих руїн перекривають посилені загони Темного Бору.', 'Перемогти 8 будь-яких істот у локації Темний Бір.', 'Рунний Майстер передав мені копію відновлених рядків. Старі руїни розташовані за зараженою ділянкою, але прямий шлях до них перекритий.\n\nРозвідники не можуть наблизитися до кам’яних споруд через постійні патрулі. Ці загони краще споряджені за звичайних дозорних і не відходять далеко від маршруту.\n\nПереможи вісім ворогів уздовж позначеної стежки. Не заходь усередину руїн. Зараз потрібно лише звільнити підхід.', 'Охорону на дорозі до старих руїн розбито. Розвідники отримали доступ до зовнішньої частини ділянки.', 114, 5.29, {'reward_formula': None, 'progress_text': 'Зачистка дороги до руїн: {progress}/8'}),
    V2StoryQuestContentRecord('dark_forest_093_sign_above_the_gate', 93, 'Знак над брамою', 'TALK', 'dark_forest', 10, 'dark_forest_092_road_to_the_ruins', 'mercenary_head', 'mercenary_head', 1, 'Після очищення дороги розвідники змогли оглянути зовнішню частину старих руїн.', 'Отримати від Голови Найманців результати огляду старих руїн.', 'Розвідники наблизилися до руїн. Кам’яні споруди значно старші за гоблінські табори, але їх нещодавно укріпили дерев’яними загородженнями.\n\nНад центральним проходом закріплено металевий знак. Здалеку видно лише його верхню частину, схожу на корону. Такий самий символ був на відновленому фрагменті наказу.\n\nБіля брами чергують стражі, а сам знак закріплений надто високо, щоб роздивитися деталі з безпечної відстані.', 'Голова Найманців передає опис укріплених руїн і символу над центральним проходом.', 114, 5.29, {'reward_formula': None}),
    V2StoryQuestContentRecord('dark_forest_094_symbol_of_the_old_ruins', 94, 'Символ старих руїн', 'QUEST_ITEM', 'dark_forest', 10, 'dark_forest_093_sign_above_the_gate', 'mercenary_head', 'mercenary_head', 1, 'Потрібно знайти частину знака зі старих руїн, на якій збереглося повне зображення.', 'Шукати під час полювання фрагмент символу зі старих руїн.', 'Під час сутичок біля руїн частина зовнішніх укріплень була пошкоджена. На землі могли залишитися уламки металевого знака.\n\nЗнайди фрагмент, на якому збереглася хоча б частина центрального зображення. Звичайні шматки металу не допоможуть визначити значення символу.\n\nНе намагайся самостійно очищати рунічні лінії, якщо вони є на поверхні.', 'Біля старих руїн знайдено металевий уламок із частиною корони та рунічного кола.', 114, 5.29, {'reward_formula': None, 'quest_item': {'item_key': 'dark_forest_royal_seal_fragment', 'display_name': 'Уламок королівської печатки', 'quantity': 1, 'drop_chance': 0.15, 'drop_location_id': 'dark_forest', 'drop_message': '🧩 Сюжетна знахідка: Уламок королівської печатки'}, 'first_drop_text': 'Серед уламків знайдено важкий металевий фрагмент. На поверхні збереглася частина корони, три зубці та тонке рунічне коло.', 'progress_text': 'Пошук фрагмента символу: {progress}/1', 'item_reveal_policy': {'pre_reveal_title': 'Символ старих руїн', 'post_reveal_title': 'Символ старих руїн', 'reveal_on_first_drop': True}, 'next_route': {'npc_id': 'rune_master', 'route_text': '🏙️ Місто → ⚒️ Ремісничий квартал → 💠 Рунний Майстер'}}),
    V2StoryQuestContentRecord('dark_forest_095_crown_and_three_prongs', 95, 'Корона і три зубці', 'TURN_IN', 'dark_forest', 10, 'dark_forest_094_symbol_of_the_old_ruins', 'rune_master', 'rune_master', 1, 'Передати Рунному Майстру уламок символу для перевірки рунічних ліній.', 'Передати Рунному Майстру уламок королівської печатки.', 'Поклади уламок у захисне коло. Рунічна лінія на поверхні ще зберігає слабкий заряд.\n\nКорона й три зубці утворюють єдиний знак. Він не позначає окремий маршрут або табір, як попередні жетони. Це символ влади над усіма гоблінськими загонами Темного Бору.\n\nРунічне коло навколо символу додали пізніше. Воно пов’язує печатку з обрядами та амулетами, але сама корона має гоблінське походження.\n\nОтже, служителі культу не замінили гоблінського правителя. Вони уклали з ним союз або підкорили його своїм впливом.', 'Рунний Майстер приймає уламок і підтверджує, що корона з трьома зубцями є символом верховної влади над гоблінськими загонами Темного Бору.', 114, 5.29, {'reward_formula': None, 'required_quest_items': [{'item_key': 'dark_forest_royal_seal_fragment', 'quantity': 1, 'consume': True}], 'next_route': {'npc_id': 'mercenary_head', 'route_text': '🏙️ Місто → 📜 Гільдія Найманців → ⚔️ Голова Найманців'}}),
    V2StoryQuestContentRecord('dark_forest_096_one_whom_the_patrols_serve', 96, 'Той, кому служать дозори', 'TALK', 'dark_forest', 10, 'dark_forest_095_crown_and_three_prongs', 'mercenary_head', 'mercenary_head', 1, 'Голова Найманців зіставив висновок Рунного Майстра зі свідченнями розвідників.', 'Отримати від Голови Найманців висновок про правителя гоблінських загонів.', 'Розвідники давно чули один і той самий титул, але не розуміли, кого саме мають на увазі гобліни.\n\nПід час зміни варти дозорні говорили про накази Короля. На ящиках, жетонах і сигнальних рогах використовували різні позначки, але всі маршрути зрештою ведуть до руїн із короною над брамою.\n\nТепер сумнівів немає. Гоблінськими загонами Темного Бору керує Король Гоблінів. Рунічний культ постачає його воїнам амулети й проводить обряди на підконтрольній території.\n\nНаскільки сильно корупція вплинула на самого Короля, поки невідомо.', 'Голова Найманців підтверджує, що старі руїни належать Королю Гоблінів, якому підпорядковуються дозори Темного Бору.', 114, 5.29, {'reward_formula': None}),
    V2StoryQuestContentRecord('dark_forest_097_outer_guard', 97, 'Зовнішня охорона', 'KILL_REGION', 'dark_forest', 10, 'dark_forest_096_one_whom_the_patrols_serve', 'mercenary_head', 'mercenary_head', 10, 'Перед підготовкою загону потрібно послабити зовнішню охорону старих руїн.', 'Перемогти 10 будь-яких істот у локації Темний Бір.', 'Руїни захищають кілька ліній варти. Поки зовнішні загони залишаються на місці, наші люди не зможуть утримати шлях до центрального проходу.\n\nПослаб охорону навколо руїн. Не заходь усередину й не намагайся знайти Короля самостійно.\n\nПісля десяти перемог повернися до мене. Загін має знати, чи зможе втримати відкритий прохід.', 'Зовнішню охорону старих руїн послаблено. Шлях до центрального проходу більше не контролюють передові гоблінські загони.', 114, 5.29, {'reward_formula': None, 'progress_text': 'Зачистка зовнішньої охорони: {progress}/10'}),
    V2StoryQuestContentRecord('dark_forest_098_before_the_decisive_campaign', 98, 'Перед вирішальним походом', 'TALK', 'dark_forest', 10, 'dark_forest_097_outer_guard', 'mercenary_head', 'mercenary_head', 1, 'Голова Найманців повідомляє про стан загону після послаблення зовнішньої охорони.', 'Отримати від Голови Найманців підсумок підготовки загону.', 'Зовнішній шлях утримується. Розвідники закріпилися біля кам’яного проходу, а гоблінські загони відійшли до внутрішньої частини руїн.\n\nКоваль завершив перевірку спорядження, Алхімік передав захисні суміші, а Рунний Майстер підготував засоби проти рунічного впливу.\n\nЗагін готовий рухатися до центральної брами. Після початку походу дороги назад не перекриють, але Король може використати всю силу руїн і своїх слуг.', 'Голова Найманців підтверджує, що спорядження, захисні засоби й шлях до центральної брами підготовлені.', 114, 5.29, {'reward_formula': None}),
    V2StoryQuestContentRecord('dark_forest_099_goblin_king', 99, 'Король Гоблінів', 'BOSS', 'dark_forest', 10, 'dark_forest_098_before_the_decisive_campaign', 'mercenary_head', 'mercenary_head', 1, 'Після довгої підготовки шлях до старих руїн відкрито. Настав час покласти край владі Короля Гоблінів над загонами Темного Бору.', 'Перемогти Короля Гоблінів і доповісти Голові Найманців.', 'Усе готово. Зовнішню охорону послаблено, шлях до центральної брами відкритий, а наш загін утримує підступи до руїн.\n\nКороль Гоблінів більше не зможе керувати дозорами з безпечного укриття. Якщо він хоче зберегти владу над Темним Бором, йому доведеться прийняти бій.\n\nНе недооцінюй його. Король пережив безліч сутичок, тримає біля себе найсильніших воїнів і користується підтримкою рунічного культу. Печатка з руїн доводить, що корупція могла торкнутися і його.\n\nВирушай у Темний Бір і натисни «👀 Роззирнутися». Там Короля Гоблінів можна викликати на бій. Також він може зустрітися випадково під час звичайного полювання. Якщо ще не готовий до бою, продовжуй підготовку та повернися до виклику пізніше.\n\nПереможи Короля Гоблінів. Після бою повернися до мене з доповіддю.', 'Голова Найманців приймає доповідь про перемогу над Королем Гоблінів.\n\nГоблінські загони втратили верховного правителя, а старі руїни більше не є центром їхнього командування. Підготовка загону дала змогу втримати підступи та не дозволила охороні втрутитися у вирішальний бій.', 190, 8.81, {'reward_formula': None, 'boss_key': 'goblin_king', 'encounter_paths': ['rng_hunt', 'guaranteed_story_call'], 'guaranteed_call_after_success': 'blocked', 'retry_after_defeat_or_escape': 'allowed', 'boss_combat_reward_is_separate': True, 'progress_text': 'Перемогти Короля Гоблінів: {progress}/1. Після перемоги повернутися до Голови Найманців.', 'required_quest_items': [], 'boss_story_policy': {'boss_key': 'goblin_king', 'random_hunt_encounter_allowed': True, 'forced_invocation_allowed': True, 'forced_invocation_surface': 'look_around_inline', 'boss_level_source': 'current_player_level', 'victory_progress': 'set 1/1 only for correct boss_key and dark_forest', 'completion_mode': 'deferred_turn_in_to_mercenary_head', 'story_reward_owner': 'quest_99_turn_in_completion', 'combat_reward_owner': 'canonical_boss_victory', 'defeat_retry': True, 'manual_escape_retry': True, 'auto_escape_retry': True, 'forced_invocation_after_victory': False, 'stale_callback_after_victory': 'reject_and_point_to_mercenary_head', 'double_callback_guard': 'canonical_active_encounter_guard', 'anti_farm': 'progress 1/1 immediately disables forced invocation before quest turn-in'}, 'next_route': {'npc_id': 'elder', 'route_text': '🏙️ Місто → 🏛️ Ратуша → 🗣️ Староста'}}),
    V2StoryQuestContentRecord('dark_forest_100_dark_forest_complete', 100, 'Завершення Темного Бору', 'TURN_IN', 'dark_forest', 10, 'dark_forest_099_goblin_king', 'elder', 'elder', 1, 'Доповісти Старості про перемогу над Королем Гоблінів і завершити історію Темного Бору.', 'Доповісти Старості про перемогу над Королем Гоблінів.', 'Староста чекає остаточної доповіді про старі руїни, Короля Гоблінів і наслідки вирішального бою.', 'Староста вислуховує доповідь про перемогу над Королем Гоблінів.\n\nБез верховного правителя гоблінські дозори втратили спільне командування. Частина загонів залишила старі руїни, а решта відступила в глибину лісу. Рунічний культ утратив основного союзника та укріплений центр у Темному Борі.\n\nМіські розвідники отримали можливість безпечніше пересуватися старими стежками, а заражені ділянки залишилися під наглядом Рунного Майстра й Алхіміка.\n\n✅ Розділ «Король Гоблінів» завершено.\n✅ Історію «Темний Бір» завершено.', 114, 5.29, {'reward_formula': None, 'required_quest_items': [], 'itemless_turn_in_policy': {'enabled': True, 'purpose': 'campaign_final_report', 'button_text': '🗣️ Доповісти Старості'}}),
)

def validate_story_dark_forest_91_100() -> None:
    quests=STORY_DARK_FOREST_91_100
    if len(quests)!=10 or [q.number for q in quests]!=list(range(91,101)): raise ValueError('invalid_package_identity')
    if len({q.quest_id for q in quests})!=10: raise ValueError('duplicate_quest_id')
    if quests[0].previous_quest_id!='dark_forest_090_corrupted_lands': raise ValueError('invalid_story_bridge')
    for previous,current in zip(quests,quests[1:]):
        if current.previous_quest_id!=previous.quest_id: raise ValueError('invalid_predecessor_chain')
    for quest in quests:
        if quest.unlock_level!=10 or quest.location_id!='dark_forest': raise ValueError('invalid_level_or_location')
        if quest.reward_exp < 0 or quest.reward_gold < 0: raise ValueError('invalid_reward')

validate_story_dark_forest_91_100()
